import sys

from importer import import_users


class Store:
    def __init__(self):
        self.rows = []

    def add(self, email, name):
        self.rows.append((email, name))


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    store = Store()
    print(import_users(argv[0], store), "users imported")


if __name__ == "__main__":
    main()
